// Demo fallback: serves fixtures/*.json (generated by `npm run fixtures` from the synthetic model).
// These are SYNTHETIC. The API marks them `mode: "demo"` and the UI labels them "Sýnigögn".
// The fixture dates are shifted to today so the presentation always looks current.
import { readFileSync } from 'node:fs';
import { utcMidnight } from '../lib/time.js';

const load = name => JSON.parse(readFileSync(new URL(`../../fixtures/${name}.json`, import.meta.url), 'utf8'));

export function demoForecast(now = new Date(), reason = '', sources = []) {
  const f = load('forecast');
  return { ...f, mode: 'demo', demoReason: reason, start: utcMidnight(now).toISOString(), nowHour: 8, generatedAt: now.toISOString(), sources };
}

export function demoHistory(now = new Date()) {
  const h = load('history');
  const end = new Date(utcMidnight(now).getTime() - 6 * 86400e3);
  const start = new Date(end.getTime() - (h.days - 1) * 86400e3);
  return { ...h, mode: 'demo', start: start.toISOString(), end: end.toISOString() };
}
